from bs4 import BeautifulSoup # <div>영역구분</div>
# pip install BeautifulSoup4
import requests
import pandas as pd
import openpyxl

data = []

for i in range(1, 5):
    url = f"https://startcoding.pythonanywhere.com/basic?page={i}"
    response = requests.get(url)
    
    if response.status_code != 200:
        print(f"[{i}페이지] 페이지를 불러오지 못했습니다. 상태 코드: {response.status_code}")
        continue

    html = response.text
    soup = BeautifulSoup(html, "html.parser")

    # 개별 상품 카드 컨테이너 선택
    items = soup.select(".product")
    print(f"[{i}페이지] 가져온 상품 개수: {len(items)}개")
    print("-" * 50)
    # response = requests.get(f"https://startcoding.pythonanywhere.com/basic?page={i}")
    # html = response.text
    # soup = BeautifulSoup(html, "html.parser")

    # items = soup.select(".product")

    # print(f"가져온 상품 개수 : {len(items)}개 \n" + "-"*30) # 상품 개수 확인

    for item in items:
        category = item.select_one(".product-category").text #카테고리
        category_name = item.select_one(".product-name").text #상품명
        #category_link = item.select_one(".product-name > a")['href'] #상품링크
        category_link = item.select_one(".product-name > a").attrs['href'] #상품 상세 페이지 링크
        # price = item.select_one(".product-price").text #가격
        price = item.select_one(".product-price").text.split("원")[0].replace(",", "") #가격
        data.append([category, category_name, category_link, price])
        print(category, category_name, category_link, price)

df = pd.DataFrame(data, columns=["카테고리","상품명","상세페이지링크","가격"])
df.to_excel("data.xlsx", index=False)




